import sys

def can_split(arr, k, x):
    """Check if we can split arr into k subsegments with minimum value >= x"""
    count = 1  # We start with one subsegment
    for num in arr:
        if num < x:
            count += 1
            if count > k:
                return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    arr = list(map(int, data[2:2+n]))

    # Binary search on the answer
    left, right = -10**9, 10**9
    answer = -10**9

    while left <= right:
        mid = (left + right) // 2
        if can_split(arr, k, mid):
            answer = mid
            left = mid + 1
        else:
            right = mid - 1

    print(answer)

if __name__ == "__main__":
    solve()
"}

