def count_multiples(frequencies, si):
    """Count how many strengths are multiples of si."""
    count = 0
    for sj, freq in frequencies.items():
        if sj % si == 0:
            count += freq
    return count

def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    n = int(next(data))
    strengths = [int(next(data)) for _ in range(n)]
    t = int(next(data))

    # Precompute prefix sums for each strength value
    # We'll use a dictionary to store counts in ranges
    prefix = {}

    # For each strength value, store a list of indices where it appears
    strength_indices = {}
    for i, s in enumerate(strrengths):
        if s not in strength_indices:
            strength_indices[s] = []
        strength_indices[s].append(i + 1)  # 1-indexed

    # For each query
    for _ in range(t):
        l = int(next(data))
        r = int(next(data))

        # Count frequencies in [l, r]
        frequencies = {}
        for s, indices in strength_indices.items():
            count = 0
            for idx in indices:
                if l <= idx <= r:
                    count += 1
            if count > 0:
                frequencies[s] = count

        # For each ant in [l, r], count how many multiples it has
        freed_ants = 0
        for i in range(l, r + 1):
            si = strengths[i - 1]
            # Count how many strengths in [l, r] are multiples of si
            points = 0
            for sj, freq in frequencies.items():
                if sj % si == 0:
                    points += freq

            if points == (r - l):
                freed_ants += 1

        # Eaten ants = total ants - freed ants
        eaten = (r - l + 1) - freed_ants
        print(eaten)

solve()
"}

