def longest_path(graph, start, visited, path):
    """Find the longest path starting from `start`"""
    max_len = 1
    visited.add(start)
    path.append(start)

    for neighbor in graph[start]:
        if neighbor not in visited:
            # Try to extend the path
            path_len = longest_path(graph, neighbor, visited, path)
            max_len = max(max_len, path_len)

