import sys

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m1 = int(next(it))
    m2 = int(next(it))

    # Read Mocha's edges
    mocha_edges = []
    for _ in range(m1):
        u = int(next(it))
        v = int(next(it))
        mocha_edges.append((u, v))

    # Read Diana's edges
    diana_edges = []
    for _ in range(m2):
        u = int(next(it))
        v = int(next(it))
        diana_edges.append((u, v))

    # Find connected components for Mocha
    parent_mocha = list(range(n + 1))
    rank_mocha = [1] * (n + 1)
    for u, v in mocha_edges:
        union(parent_mocha, rank_mocha, u, v)

    # Find connected components for Diana
    parent_diana = list(range(n + 1))
    rank_diana = [1] * (n + 1)
    for u, v in diana_edges:
        union(parent_diana, rank_diana, u, v)

    # Find all possible edges that can be added
    possible_edges = []
    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            if find(parent_mocha, u) != find(parent_mocha, v) and find(parent_diana, u) != find(parent_diana, v):
                possible_edges.append((u, v))

    # We need to add h edges
    h = n - 1 - max(m1, m2)

    # Use union-find to add edges without creating cycles
    parent_add = list(range(n + 1))
    rank_add = [1] * (n + 1)
    result = []

    for u, v in possible_edges:
        if find(parent_add, u) != find(parent_add, v):
            union(parent_add, rank_add, u, v)
            result.append((u, v))
            if len(result) == h:
                break

    print(h)
    for u, v in result:
        print(u, v)

