    """Find a cycle in the graph."""
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)

    def dfs(u, parent):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                parent[v] = u
                if dfs(v, parent):
                    return True
            elif parent[u] != v:
                # Found a cycle
                cycle = []
                current = u
                while current != v:
                    cycle.append(current)
                    current = parent[current]
                cycle.append(v)
                cycle.reverse()
                return cycle
        return False

