def count_lucky_numbers(n):
    """Count how many lucky numbers are less than or equal to n"""
    s = str(n)
    length = len(s)

    # Count numbers with fewer digits
    count = 0
    for d in range(1, length):
        count += 2 ** d

    # Now count numbers with the same number of digits
    # We use dynamic programming approach

    # dp[i][tight]: number of ways to form a number with i digits, where tight indicates
    # if we are still constrained by the corresponding digit in n
    dp = [[0, 0] for _ in range(length + 1)]
    dp[0][1] = 1  # Start with an empty number

    for i in range(length):
        for tight in [0, 1]:
            if dp[i][tight] == 0:
                continue

            # Try placing 4
            if tight:
                if 4 < int(s[i]):
                    dp[i+1][0] += dp[i][tight]
                elif 4 == int(s[i]):
                    dp[i+1][1] += dp[i][tight]
            else:
                dp[i+1][0] += dp[i][tight]

            # Try placing 7
            if tight:
                if 7 < int(s[i]):
                    dp[i+1][0] += dp[i][tight]
                elif 7 == int(s[i]):
                    dp[i+1][1] += dp[i][tight]
            else:
                dp[i+1][0] += dp[i][tight]

    return count + dp[length][0] + dp[length][1]

