import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    n = int(data[0])

    # Track points for each participant
    points = {}
    # Track when each participant reached each points value
    reached = {}

    for i in range(1, n + 1):
        line = data[i].strip()
        name, score = line.split()
        score = int(score)

        # Update points
        if name in points:
            points[name] += score
        else:
            points[name] = score

        # Record when this participant reached this points value
        if name not in reached:
            reached[name] = {}

        # If this is the first time they reached this points value,
        # record the round number (1-indexed)
        if points[name] not in reached[name]:
            reached[name][points[name]] = i

    # Find the maximum points value
    max_points = max(points.values())

    # Among participants with max points, find who reached max points first
    winner = None
    for name in points:
        if points[name] == max_points:
            # Check if they reached max points
            if max_points in reached[name]:
                # They reached max points, check if they're the first
                if winner is None or reached[name][max_points] < reached[winner][max_points]:
                    winner = name

    print(winner)

if __name__ == "__main__":
    solve()
