import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))

    # Union-Find data structure
    parent = list(range(N + 1))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu != pv:
            parent[pu] = pv

    # Read friendships
    for _ in range(M):
        a = int(next(it))
        b = int(next(it))
        union(a, b)

    # Find size of each component
    component_size = [0] * (N + 1)
    for i in range(1, N + 1):
        component_size[find(i)] += 1

    # Read blockships
    blockships = set()
    for _ in range(K):
        c = int(next(it))
        d = int(next(it))
        blockships.add((c, d))
        blockships.add((d, c))

    # Calculate answers
    result = []
    for i in range(1, N + 1):
        comp = find(i)

        # Count users in the same component
        count = 0
        for j in range(1, N + 1):
            if find(j) == comp:
                count += 1

        # Subtract self
        count -= 1

        # Subtract direct friends
        for j in range(1, N + 1):
            if find(j) == comp and j != i:
                if find(j) == find(i) and j != i:
                    count -= 1

        # Subtract direct blockships
        for j in range(1, N + 1):
            if (i, j) in blockships:
                count -= 1

        result.append(str(count))

    print(' '.join(result))

if __name__ == '__main__':
    solve()
"}

