import sys

def is_beneficial(i):
    """Determine if operation i is beneficial."""
    if i == 1:
        return True

    # Find prime factorization of i
    # Find p_max: prime with greatest exponent, smallest in case of tie

    # Get prime factors and their exponents
    factors = {}
    temp = i
    for p in range(2, int(temp**0.5) + 1):
        while temp % p == 0:
            factors[p] = factors.get(p, 0) + 1
            temp //= p
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Find p_max
    max_exponent = max(factors.values())
    candidates = [p for p, exp in factors.items() if exp == max_exponent]
    p_max = min(candidates)

    # Check if beneficial
    return (i % p_max) % 2 == 1

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    L = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    for i in range(1, L + 1):
        if not A:
            continue

        if is_beneficial(i):
            # Beneficial: double the largest element
            if A:
                max_val = max(A)
                idx = A.index(max_val)
                A[idx] *= 2
        else:
            # Harmful: divide the smallest element that won't become 0
            if A:
                for val in A:
                    if val % 2 == 0:
                        # Dividing by 2 won't make it 0
                        idx = A.index(val)
                        A[idx] //= 2
                        break
                    elif val == 1:
                        # Dividing 1 by 2 gives 0, remove it
                        idx = A.index(val)
                        A.pop(idx)
                        break

    # Output results
    print(len(A))
    if A:
        print(' '.join(str(val) for val in sorted(A)))
    else:
        print()

if __name__ == "__main__":
    solve()
