def is_point_on_segment(p, a, b):
    """Check if point p lies on segment ab"""
    # Check if p is collinear with a and b
    cross_product = (a[1] - p[1]) * (b[0] - a[0]) - (a[0] - p[0]) * (b[1] - a[1])
    if abs(cross_product) > 1e-9:
        return False

    # Check if p is between a and b
    dot_product = (p[0] - a[0]) * (b[0] - a[0]) + (p[1] - a[1]) * (b[1] - a[1])
    if dot_product < 0:
        return False

    squared_length = (b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2
    if dot_product > squared_length:
        return False

    return True

def dot_product(v1, v2):
    return v1[0] * v2[0] + v1[1] * v2[1]

def angle_between_segments(seg1, seg2):
    """Check if angle between segments is between 0 and 90 degrees"""
    # Find common endpoint
    common_endpoints = []
    for p1 in seg1:
        for p2 in seg2:
            if p1 == p2:
                common_endpoints.append((p1, p2))

    if not common_endpoints:
        return False

    # Get vectors from common endpoint
    for common in common_endpoints:
        a, b = common
        # Get vectors from a to other endpoints
        vec1 = (seg1[0] if seg1[1] == a else seg1[1], a)
        vec2 = (seg2[0] if seg2[1] == a else seg2[1], a)

        # Check if vectors are valid (not zero length)
        if vec1[0] == vec1[1] or vec2[0] == vec2[1]:
            continue

        # Calculate angle using dot product
        dot = dot_product((vec1[0][0] - vec1[1][0], vec1[0][1] - vec1[1][1]),
                         (vec2[0][0] - vec2[1][0], vec2[0][1] - vec2[1][1]))
        len1 = (vec1[0][0] - vec1[1][0]) ** 2 + (vec1[0][1] - vec1[1][1]) ** 2
        len2 = (vec2[0][0] - vec2[1][0]) ** 2 + (vec2[0][1] - vec2[1][1]) ** 2

        if len1 == 0 or len2 == 0:
            continue

        cos_theta = dot / (len1 ** 0.5 * len2 ** 0.5)

        # Angle between 0 and 90 degrees (cos(theta) between 0 and 1)
        if 0 < cos_theta <= 1:
            return True
    return False

def proportion_check(seg, point):
    """Check if point divides segment in proportion >= 1/4"""
    a, b = seg
    # Check if point is on segment
    if not is_point_on_segment(point, a, b):
        return False

    # Calculate distances
    len1 = (point[0] - a[0]) ** 2 + (point[1] - a[1]) ** 2
    len2 = (b[0] - point[0]) ** 2 + (b[1] - point[1]) ** 2
    len_total = len1 + len2

    # Check proportions
    if len1 / len_total < 1/4 or len2 / len_total < 1/4:
        return False

    return True

def solve():
    t = int(input())
    for _ in range(t):
        seg1 = list(map(int, input().split()))
        seg2 = list(map(int, input().split()))
        seg3 = list(map(int, input().split()))

        # Check all permutations
        for i in range(3):
            for j in range(3):
                if i == j:
                    continue
                k = 3 - i - j

                # Check if segments i and j share an endpoint
                common = False
                for p1 in [seg1, seg2, seg3][i]:
                    for p2 in [seg1, seg2, seg3][j]:
                        if p1 == p2:
                            common = True
                            break
                    if common:
                        break

                if not common:
                    continue

                # Check if segment k connects points on the other two segments
                seg_a = [seg1, seg2, seg3][i]
                seg_b = [seg1, seg2, seg3][j]
                seg_c = [seg1, seg2, seg3][k]

                if not (is_point_on_segment(seg_c[0], seg_a[0], seg_a[1]) and
                        is_point_on_segment(seg_c[1], seg_b[0], seg_b[1])):
                    continue

                # Check angle condition
                if not angle_between_segments(seg_a, seg_b):
                    continue

                # Check proportion conditions
