import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    while True:
        n = int(data[idx])
        idx += 1
        if n == 0:
            break

        cities = []
        for _ in range(n):
            cities.append(data[idx])
            idx += 1

        # Precompute overlaps
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    # Longest common suffix of cities[i] and prefix of cities[j]
                    min_len = min(len(cities[i]), len(cities[j]))
                    for k in range(min_len, 0, -1):
                        if cities[i][-k:] == cities[j][:k]:
                            overlap[i][j] = k
                            break

        # DP: dp[mask][i] = shortest superstring including cities in mask, ending with city i
        INF = float('inf')
        dp = [[INF] * n for _ in range(1 << n)]

        # Initialize: single city
        for i in range(n):
            dp[1 << i][i] = len(cities[i])

        # DP transition
        for mask in range(1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue

                if dp[mask][i] == INF:
                    continue

                # Try to add another city j
                for j in range(n):
                    if mask & (1 << j):
                        continue

                    new_mask = mask | (1 << j)
                    new_len = dp[mask][i] + len(cities[j]) - overlap[i][j]
                    if new_len < dp[new_mask][j]:
                        dp[new_mask][j] = new_len

        # Find the minimum length
        min_len = min(dp[(1 << n) - 1][i] for i in range(n))
        print(min_len)

if __name__ == "__main__":
    solve()
"}

