    from collections import defaultdict

    left = 0
    freq = defaultdict(int)
    distinct = 0

    for right in range(n):
        # Add a[right] to the window
        if freq[a[right]] == 0:
            distinct += 1
        freq[a[right]] += 1

        # If we have more than k distinct, move left
        while distinct > k:
            freq[a[left]] -= 1
            if freq[a[left]] == 0:
                distinct -= 1
            left += 1

        # If we have exactly k distinct, check if it's minimal by inclusion
        if distinct == k:
            # Check if each distinct element appears at least twice
            valid = True
            for val in freq:
                if freq[val] < 2:
                    valid = False
                    break

            if valid:
                print(f"{left + 1} {right + 1}")
                return

    print("-1 -1")

