    """Hopcroft-Karp algorithm for maximum bipartite matching"""
    pair_u = [-1] * (n + 1)
    pair_v = [-1] * (n + 1)
    dist = [0] * (n + 1)
    result = 0
    visited = [False] * (n + 1)
    while bfs(dist, pair_u, pair_v, visited):
        for u in range(1, n + 1):
            if pair_u[u] == -1:
                if dfs(u, visited, dist, pair_u, pair_v):
                    result += 1
    return result

