import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    results = []

    for _ in range(t):
        a = int(data[idx])
        b = int(data[idx+1])
        c = int(data[idx+2])
        m = int(data[idx+3])
        idx += 4

        # Check if m is achievable
        if m == 0:
            results.append("YES")
            continue

        # Check if we have at least one letter with count > 1
        if a == 1 and b == 1 and c == 1:
            results.append("NO")
            continue

        # Calculate maximum possible adjacent equal pairs
        max_m = 0
        if a > 1:
            max_m += a - 1
        if b > 1:
            max_m += b - 1
        if c > 1:
            max_m += c - 1

        # Check if m is within range
        if 0 <= m <= max_m:
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

