MOD = 1000000007

# Precompute factorials and inverse factorials up to 10^5
max_n = 100000
fact = [1] * (max_n + 1)
in_fact = [1] * (max_n + 1)
for i in range(1, max_n + 1):
    fact[i] = fact[i-1] * i % MOD
for i in range(max_n, 0, -1):
    in_fact[i] = in_fact[i+1] * i % MOD

def comb(n, k):
    """Compute combination C(n, k) modulo MOD"""
    if n < 0 or k < 0 or n < k:
        return 0
    return fact[n] * in_fact[k] % MOD * in_fact[n - k] % MOD

# Precompute smallest prime factor (SPF) for Möbius function
spf = [0] * (max_n + 1)
for i in range(2, max_n + 1):
    if spf[i] == 0:
        spf[i] = i
        for j in range(i * i, max_n + 1, i):
            if spf[j] == 0:
                spf[j] = i

# Precompute Möbius function
mu = [1] * (max_n + 1)
for i in range(2, max_n + 1):
    if spf[i] == i:
        # i is prime
        mu[i] = -1
    else:
        # i is composite
        p = spf[i]
        if i // p % p == 0:
            # i has a squared prime factor
            mu[i] = 0
        else:
            # i has distinct prime factors
            mu[i] = mu[i // p] * -1

# Read input and process queries
q = int(input())
for _ in range(q):
    n, f = map(int, input().split())

    # Find all divisors of n
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)

    # Compute answer using Möbius inversion
    ans = 0
    for d in divisors:
        c = comb(n // d - 1, f - 1)
        ans = (ans + mu[d] * c) % MOD

    print(ans)
