def is_k_beautiful(x, k):
    """Check if x is k-beautiful"""
    digits = set(str(x))
    return len(digits) <= k

def find_min_k_beautiful(n, k):
    """Find the minimum k-beautiful number ≥ n"""
    if k == 1:
        # Try each single digit from 1 to 9
        for d in range(1, 10):
            # Find the smallest number made of digit d that is ≥ n
            length = len(str(n))
            candidate = int(str(d) * length)
            if candidate < n:
                # Need to increase the length
                candidate = int(str(d) * (length + 1))
            if is_k_beautiful(candidate, k):
                return candidate
        return -1
