        # Try all pairs of digits
        for d1 in range(1, 10):
            for d2 in range(0, 10):
                if d1 == d2:
                    continue
                # Try to construct the smallest number ≥ n using only d1 and d2
                # Start with the same length as n
                length = len(str(n))
                # Try all combinations of d1 and d2 of this length
                for mask in range(1, 1 << length):
